package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
import java.util.*;
public class PushLearningTest {
 @Test public void frozenCasesAndBaselineSourcesRemainOriginal() throws Exception {Path repo=Path.of("").toAbsolutePath();while(repo!=null&&!Files.exists(repo.resolve("docs/PUSH_032_FROZEN_CONTRACT.json")))repo=repo.getParent();assertNotNull(repo);var contract=new JSONObject(Files.readString(repo.resolve("docs/PUSH_032_FROZEN_CONTRACT.json")));var path=repo.resolve("workspace-engine/src/main/resources/push-evaluation032.json");assertEquals(contract.getString("suiteSha256"),MapDefinition.sha(Files.readString(path).replace("\r\n","\n").getBytes(java.nio.charset.StandardCharsets.UTF_8)));for(Object raw:contract.getJSONArray("preservedNativeSources")){var f=(JSONObject)raw;assertEquals(f.getString("path"),f.getString("sha256"),MapDefinition.sha(Files.readString(repo.resolve(f.getString("path"))).replace("\r\n","\n").getBytes(java.nio.charset.StandardCharsets.UTF_8)));}var suite=PushLearning.suite();assertEquals(4,PushLearning.cases(suite,"training").length());assertEquals(8,PushLearning.cases(suite,"evaluation").length());for(Object raw:suite.getJSONArray("cases"))assertTrue(PushLearning.plan(suite,(JSONObject)raw,UUID.randomUUID().toString(),8).getBoolean("passed"));}
 @Test public void actualNativeTrainingAndReservedComparison() throws Exception {var root=Files.createTempDirectory("force-learning032-");String id=UUID.randomUUID().toString();try(var store=new PushLearningStore(root)){store.start(id,UUID.randomUUID().toString());JSONObject j=null;for(int n=0;n<12000;n++){j=store.read(id);if(!j.getString("status").equals("running"))break;Thread.sleep(10);}assertEquals(j.toString(),"completed",j.getString("status"));assertEquals(32,j.getJSONArray("trials").length());var decision=store.verify(id);System.out.println("NATIVE_LEARNING_032 "+decision);assertTrue(j.getJSONObject("decision").similar(decision));assertEquals(16,j.getInt("selectionAfterTrial"));assertEquals(8,decision.getInt("evaluationCases"));assertEquals("baseline-031",store.activeProfile().getString("id"));
 var evaluatedOnly=new JSONArray(j.getJSONArray("trials").toString());for(Object raw:evaluatedOnly){var row=(JSONObject)raw;if(row.getString("split").equals("evaluation"))row.getJSONObject("metrics").put("timeS",.01);}assertTrue(j.getJSONObject("selection").similar(PushLearning.select(j.getJSONObject("suite"),evaluatedOnly)));
 var frames=new JSONArray();for(Object raw:PushLearningReport.charts(j)){var c=(JSONObject)raw;frames.put(new JSONObject().put("mode",c.getString("mode")).put("lines",c.getJSONArray("lines")));}var view=new JSONObject().put("visible",true).put("rows",PushLearningReport.table(j)).put("data",PushLearningReport.data(j)).put("frames",frames);assertTrue(PushLearningReport.verifyView(j,view).getBoolean("passed"));
 final JSONObject completed=j;var wrongCell=new JSONObject(view.toString());wrongCell.getJSONArray("rows").getJSONArray(0).put(1,"invented");assertThrows(IllegalStateException.class,()->PushLearningReport.verifyView(completed,wrongCell));var wrongPoint=new JSONObject(view.toString());wrongPoint.getJSONArray("frames").getJSONObject(2).getJSONArray("lines").getJSONArray(1).getJSONArray(0).put(1,999);assertThrows(IllegalStateException.class,()->PushLearningReport.verifyView(completed,wrongPoint));
assertThrows(IllegalStateException.class,()->store.promote(id,new JSONObject().put("passed",true)));var t=j.getJSONArray("trials").getJSONObject(0);var rawPath=root.resolve("push-learning/jobs/"+id+"/native/"+t.getString("runId")+"/result.json");String originalBytes=Files.readString(rawPath);Files.writeString(rawPath,originalBytes+" ");assertThrows(IllegalStateException.class,()->store.verify(id));Files.writeString(rawPath,originalBytes);assertTrue(store.verify(id).similar(decision));Files.writeString(root.resolve("summary.json"),j.toString());System.out.println("NATIVE_LEARNING_PROJECT_032 "+root);}}
 @Test public void persistedProfileRollbackIsExactAndRejectsAStaleExpectedVersion() throws Exception {
  var root=Files.createTempDirectory("force032-registry-control-");var p=new JSONObject().put("id","software-fixture-only").put("initialForceN",24).put("maxForceN",32).put("scope","Software persistence/rollback control only, not promoted native candidate evidence");p.put("sha256",PushLearning.hash(p));var registry=new JSONObject().put("active",p.getString("id")).put("profiles",new JSONArray().put(p)).put("history",new JSONArray().put(new JSONObject().put("kind","activate").put("from","baseline-031").put("to",p.getString("id"))));PushLearningStore.atomic(root.resolve("push-learning/state.json"),new JSONObject().put("registry",registry).put("jobs",new JSONArray()));
  try(var store=new PushLearningStore(root)){assertEquals(24,store.activeProfile().getInt("initialForceN"));assertThrows(IllegalStateException.class,()->store.rollback("stale-profile"));assertEquals("baseline-031",store.rollback(p.getString("id")).getString("id"));assertEquals(8,store.activeProfile().getInt("initialForceN"));assertEquals(24,store.profile(p.getString("id")).getInt("initialForceN"));}try(var store=new PushLearningStore(root)){assertEquals("baseline-031",store.activeProfile().getString("id"));assertEquals("rollback",store.state().getJSONArray("history").getJSONObject(1).getString("kind"));}
 }

}
